import React from 'react';
import { motion } from 'framer-motion';
import {
  AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine
} from 'recharts';

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background:'#0b0f1a', border:'1px solid rgba(0,210,255,.2)',
      borderRadius:8, padding:'8px 12px',
      fontFamily:'JetBrains Mono,monospace', fontSize:11, color:'#d8e0ec'
    }}>
      <div style={{color:'#5a6a82',marginBottom:4}}>{label}</div>
      <div>${payload[0].value.toFixed(2)}</div>
    </div>
  );
};

function buildChartData(cp, pp) {
  const diff = pp - cp;
  const labels = ['T-4','T-3','T-2','T-1','Now','T+1','T+2','T+3','T+4','Pred'];
  return labels.map((t, i) => {
    let v;
    if (i < 4) {
      // historical — simulate approach to current
      v = cp - diff * 0.15 * (4 - i) + (Math.random() - 0.5) * Math.abs(diff) * 0.25;
    } else if (i === 4) {
      v = cp;
    } else {
      // forecast
      const p = (i - 4) / 5;
      v = cp + diff * p + (Math.random() - 0.5) * Math.abs(diff) * 0.15;
    }
    return { t, v: parseFloat(v.toFixed(2)) };
  });
}

const PriceChart = ({ currentPrice, predictedPrice, direction }) => {
  const isUp   = direction?.includes('UP');
  const color  = isUp ? '#00e87a' : '#ff3b6b';
  const data   = buildChartData(currentPrice, predictedPrice);
  const yMin   = Math.min(...data.map(d => d.v)) * 0.998;
  const yMax   = Math.max(...data.map(d => d.v)) * 1.002;

  return (
    <motion.div
      className="card"
      style={{ marginBottom: 18 }}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.3 }}
    >
      <div className="card-title">
        <div className="card-ico ico-c">📈</div>
        <span className="card-title-text">Predicted Price Trajectory</span>
        <span style={{
          marginLeft:'auto', fontFamily:'JetBrains Mono,monospace',
          fontSize:9, color:'var(--muted)', letterSpacing:'.1em'
        }}>SIMULATED PATH · NOW → T+5</span>
      </div>

      <div style={{ height: 180 }}>
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top:8, right:6, bottom:0, left:0 }}>
            <defs>
              <linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%"  stopColor={color} stopOpacity={0.25} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis
              dataKey="t"
              tick={{ fill:'#3a4558', fontSize:9, fontFamily:'JetBrains Mono' }}
              axisLine={false} tickLine={false}
            />
            <YAxis
              domain={[yMin, yMax]}
              tick={{ fill:'#3a4558', fontSize:9, fontFamily:'JetBrains Mono' }}
              axisLine={false} tickLine={false} width={54}
              tickFormatter={v => `$${v.toFixed(0)}`}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine x="Now" stroke="rgba(0,210,255,0.3)" strokeDasharray="3 3" />
            <Area
              type="monotone" dataKey="v"
              stroke={color} strokeWidth={2}
              fill="url(#chartGrad)"
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
      <div className="chart-note">
        Historical data (T-4 to Now) + model projection (T+1 to Pred). Dashed line = current price point.
      </div>
    </motion.div>
  );
};

export default PriceChart;
